import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;
  const root = new Group();
  const tweens = [];
  let disposed = false;
  let loadedTexture = null;

  const palette = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const backdropMaterial = new MeshBasicNodeMaterial({
    color: new Color(palette.surface)
  });
  const backdrop = new Mesh(
    new PlaneGeometry(2.85, 2.05),
    backdropMaterial
  );
  backdrop.position.z = -0.18;
  root.add(backdrop);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: new Color(palette.ink),
    transparent: true,
    opacity: 0.72
  });
  const shadow = new Mesh(
    new PlaneGeometry(2.58, 1.72),
    shadowMaterial
  );
  shadow.position.set(0, -0.035, -0.12);
  root.add(shadow);

  const cardGroup = new Group();
  cardGroup.position.z = 0.04;
  root.add(cardGroup);

  const paperMaterial = new MeshBasicNodeMaterial({
    color: new Color(palette.paper)
  });
  const paperPlane = new Mesh(
    new PlaneGeometry(2.42, 1.58),
    paperMaterial
  );
  paperPlane.position.z = -0.025;
  cardGroup.add(paperPlane);

  const imageMaterial = new MeshBasicNodeMaterial({
    color: new Color(palette.paper)
  });
  const imagePlane = new Mesh(
    new PlaneGeometry(2.30, 1.44),
    imageMaterial
  );
  imagePlane.position.z = 0.02;
  cardGroup.add(imagePlane);

  const edgeMaterial = new MeshBasicNodeMaterial({
    color: new Color(palette.accent),
    transparent: true,
    opacity: 0.34
  });

  const edgeTop = new Mesh(new PlaneGeometry(2.42, 0.025), edgeMaterial);
  const edgeBottom = new Mesh(new PlaneGeometry(2.42, 0.025), edgeMaterial);
  const edgeLeft = new Mesh(new PlaneGeometry(0.025, 1.58), edgeMaterial);
  const edgeRight = new Mesh(new PlaneGeometry(0.025, 1.58), edgeMaterial);

  edgeTop.position.set(0, 0.777, 0.05);
  edgeBottom.position.set(0, -0.777, 0.05);
  edgeLeft.position.set(-1.197, 0, 0.05);
  edgeRight.position.set(1.197, 0, 0.05);

  cardGroup.add(edgeTop, edgeBottom, edgeLeft, edgeRight);

  const edgeMeshes = [edgeTop, edgeBottom, edgeLeft, edgeRight];

  const textureUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (textureUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(textureUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      loadedTexture = texture;
      if ('colorSpace' in texture && ctx.THREE.SRGBColorSpace) {
        texture.colorSpace = ctx.THREE.SRGBColorSpace;
      }
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const animate = (target, vars) => {
    const tween = gsap.to(target, vars);
    tweens.push(tween);
    return tween;
  };

  const handlers = {
    hover: (active = true) => {
      if (disposed) return;

      if (active) {
        animate(cardGroup.position, {
          y: 0.15,
          duration: 0.3,
          ease: 'power3.out'
        });
        animate(cardGroup.rotation, {
          x: -0.025,
          y: 0.035,
          duration: 0.3,
          ease: 'power3.out'
        });
      } else {
        animate(cardGroup.position, {
          y: 0,
          duration: 0.3,
          ease: 'power3.out'
        });
        animate(cardGroup.rotation, {
          x: 0,
          y: 0,
          duration: 0.3,
          ease: 'power3.out'
        });
      }
    },

    click: () => {
      if (disposed) return;

      animate(cardGroup.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out',
        yoyo: true,
        repeat: 1
      });

      ctx.emit?.('hub-journal.select', {
        node: config.id ?? 'journal-card-3'
      });
    },

    focus: () => {
      if (disposed) return;
      edgeMeshes.forEach((edge) => {
        animate(edge.material, {
          opacity: 1,
          duration: 0.2,
          ease: 'power2.out'
        });
      });
    },

    blur: () => {
      if (disposed) return;
      edgeMeshes.forEach((edge) => {
        animate(edge.material, {
          opacity: 0.34,
          duration: 0.25,
          ease: 'power2.out'
        });
      });
    }
  };

  root.userData.handlers = handlers;
  root.userData.stockBadge = null;

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    tweens.forEach((tween) => tween.kill());
    gsap.killTweensOf(cardGroup);
    gsap.killTweensOf(cardGroup.position);
    gsap.killTweensOf(cardGroup.rotation);
    gsap.killTweensOf(cardGroup.scale);

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();

      const material = object.material;
      if (Array.isArray(material)) {
        material.forEach((entry) => entry.dispose?.());
      } else {
        material?.dispose?.();
      }
    });

    loadedTexture?.dispose?.();
    loadedTexture = null;
  };

  return root;
}

export default createNode;
